const ESTADOS = ['Pendiente', 'EnProgreso', 'Terminada'];

function siguienteEstado(estado) {
  const posicion = ESTADOS.indexOf(estado);
  return posicion >= 0 && posicion < ESTADOS.length - 1 ? ESTADOS[posicion + 1] : null;
}

